const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let me=null,page='home',cache={},calendarCursor=new Date(),timer={left:25*60,total:25*60,mode:'work',running:false,interval:null,subject:''},cardCursor={deck:null,index:0,flipped:false};
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:me?.timezone||undefined,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),fmt=d=>new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short'}),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function csrf(){return document.cookie.split('; ').find(x=>x.startsWith('sf_csrf='))?.split('=')[1]||''}
async function api(url,opts={}){opts.headers={...(opts.headers||{})};if(!['GET','HEAD'].includes((opts.method||'GET').toUpperCase()))opts.headers['X-CSRF-Token']=decodeURIComponent(csrf());if(opts.body&&!(opts.body instanceof FormData))opts.headers['Content-Type']='application/json';let r=await fetch('/api'+url,{credentials:'same-origin',...opts});let data;try{data=await r.json()}catch{data={}}if(r.status===401){showAuth();throw Error(data.detail||'Требуется вход')}if(!r.ok)throw Error(data.detail||data.error||'Ошибка запроса');return data}
function toast(s){let t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}
