function authTab(which){$$('[data-auth]').forEach(b=>b.classList.toggle('active',b.dataset.auth===which));$('#loginForm').classList.toggle('hidden',which!=='login');$('#registerForm').classList.toggle('hidden',which!=='register');$('#authError').textContent=''}
$$('[data-auth]').forEach(b=>b.onclick=()=>authTab(b.dataset.auth));
