$('#registerForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);try{await api('/register',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});await boot()}catch(x){$('#authError').textContent=x.message}};
