function navigate(p){page=p;setMobileMenu(false);$$('[data-mobile-page]').forEach(b=>b.classList.toggle('active',b.dataset.mobilePage===p));if(['calendar','grades','cheats','cards','goals','analytics','subjects'].includes(p))$('#studyNav').open=true;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===p));let names={home:'Мой день',calendar:'Календарь',habits:'Привычки',tasks:'Домашние задания',schedule:'Расписание',grades:'Оценки',cheats:'Шпаргалки',cards:'Карточки для запоминания',goals:'Личные цели',pomodoro:'Pomodoro',analytics:'Продвинутая аналитика',telegram:'Telegram',reminders:'Напоминания',appearance:'Оформление',settings:'Настройки',developer:'Разработчик',subjects:'Заметки',search:'Поиск'};$('#pageTitle').textContent=names[p]||'My-Study';renderPage().catch(e=>toast(e.message));}
async function renderPage(){let el=$('#content');el.innerHTML='<div class="empty">Загружаем твои данные…</div>';try{let render={home:homePage,calendar:calendarPage,habits:habitsPage,tasks:tasksPage,schedule:schedulePage,grades:gradesPage,cheats:cheatsPage,cards:cardsPage,goals:goalsPage,pomodoro:pomodoroPage,analytics:analyticsPage,telegram:telegramPage,reminders:remindersPage,appearance:appearancePage,settings:settingsPage,developer:developerPage,subjects:subjectColorsPage,search:searchPage}[page];if(!render)throw Error('Неизвестный раздел');el.innerHTML=await render();bindCommon()}catch(e){el.innerHTML=`<div class="card"><h3>Не удалось загрузить раздел</h3><p class="muted">${esc(e.message||'Неизвестная ошибка')}</p><button class="primary" onclick="renderPage()">Повторить</button></div>`;throw e}}
function head(title,sub='',action=''){return `<div class="section-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`}
function stat(label,value,sub,glow='#8e7aff'){return `<div class="stat-card" style="--glow:${glow}"><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-sub">${sub||''}</div></div>`}
function empty(msg,emoji='✦'){return `<div class="empty"><div class="emoji">${emoji}</div>${msg}</div>`}
function btn(label,fn,cls='primary'){return `<button class="${cls}" data-action="${fn}">${label}</button>`}
function subjectColor(subject,colors={}){
  const saved=colors[subject];
  if(/^#[0-9a-f]{6}$/i.test(saved||''))return saved;
  const palette=['#739bff','#ad8cff','#6ccec3','#e3ad75','#da91c0'];
  const hash=Array.from(subject||'').reduce((n,c)=>(n+c.charCodeAt(0))%palette.length,0);
  return palette[hash];
}
async function homePage(){
  const [hs,ts,ls,goals,settings,colors,notes]=await Promise.all([
    api('/habits'),api('/tasks'),api('/lessons'),api('/goals'),api('/settings'),api('/subject-colors'),api('/lesson-notes')
  ]);
  cache={...cache,habits:hs,tasks:ts,lessons:ls,goals};
  const day=today(),wd=(new Date(day+'T12:00:00').getDay()+6)%7;
  const habits=hs.filter(h=>h.days.includes(wd)),done=habits.filter(h=>h.checks.includes(day)).length;
  const open=ts.filter(t=>!t.done),lessons=ls.filter(l=>l.weekday===wd).sort((a,b)=>a.period-b.period);
  const pct=habits.length?Math.round(done/habits.length*100):0;
  const hour=Number(new Intl.DateTimeFormat('en-GB',{timeZone:me.timezone||undefined,hour:'2-digit',hourCycle:'h23'}).format(new Date()));
  const hello=hour<6?'Доброй ночи':hour<12?'Доброе утро':hour<18?'Добрый день':'Добрый вечер';
  const name=esc(me.display_name||me.username||'');
  const widgets=settings.widgets.split(','),show=(id,html)=>widgets.includes(id)?html:'';
  return `<div class="day-hero"><div class="day-hero-copy"><div class="eyebrow">MY-STUDY 2.1 · В ТВОЁМ РИТМЕ</div><h2>${hello}, ${name}<span class="welcome-star">✦</span></h2><p>Для больших планов достаточно маленького шага.<br>Выбери, с чего начнёшь сегодня.</p><div class="hero-actions">${btn('＋ Добавить задание','newTask')}${btn('Начать фокус →','goPomodoro','ghost')}</div></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="hero-spark">✦</div><span class="art-label">один шаг за раз</span></div></div>
  <div class="day-metrics"><div><span class="metric-icon">▤</span><span><b>${open.length}</b><small>заданий в работе</small></span></div><div><span class="metric-icon violet">✓</span><span><b>${done}<em> / ${habits.length}</em></b><small>привычек сегодня</small></span></div><div><span class="metric-icon teal">▦</span><span><b>${lessons.length}</b><small>уроков сегодня</small></span></div><div><span class="metric-icon amber">◎</span><span><b>${goals.filter(g=>!g.done).length}</b><small>целей в движении</small></span></div></div>
  <div class="day-layout"><div class="day-primary">
  ${show('tasks',`<article class="card day-tasks">${head('Домашние задания','Всё необходимое, чтобы приступить',btn('Все задания →','goTasks','ghost'))}<div class="list">${open.slice(0,4).map(t=>`<div class="home-task" style="--subject:${subjectColor(t.subject,colors)}"><label class="task-check-label"><input class="check" type="checkbox" data-taskdone="${t.id}" aria-label="Выполнить ${esc(t.title)}"></label><div class="grow"><div class="task-meta"><span class="subject-badge">${esc(t.subject||'Без предмета')}</span><span>${t.due?'К '+fmt(t.due):'Без срока'}</span></div><b>${esc(t.title)}</b>${t.description?`<p class="task-description">${esc(t.description)}</p>`:''}<div class="task-inline-actions">${t.attachments?.length?`<button class="ghost" data-home-photo="${t.id}">▧ Фото · ${t.attachments.length}</button>`:''}<button class="ghost" data-action="goTasks">Открыть задание ↗</button></div></div></div>`).join('')||empty('Свободное место для новых идей. Все задания выполнены!','✓')}</div><button class="add-inline" data-action="newTask">＋ Добавить домашнее задание</button></article>`)}
  ${show('schedule',`<article class="card day-schedule">${head('Уроки сегодня','Твой маршрут на день',btn('Расписание →','goSchedule','ghost'))}<div class="lesson-timeline">${lessons.map(l=>`<div class="timeline-lesson" style="--subject:${subjectColor(l.subject,colors)}"><div class="lesson-time"><b>${esc(l.start||'—')}</b><small>${esc(l.finish||'')}</small></div><span class="timeline-dot"></span><div><b>${esc(l.subject)}</b><small>${l.period} урок${l.room?' · '+esc(l.room):''}</small>${notes[l.subject]?`<p class="task-description">${esc(notes[l.subject])}</p>`:''}</div></div>`).join('')||empty('Сегодня уроков нет. Время для своих планов.','▦')}</div></article>`)}
  </div><div class="day-secondary">
  ${show('habits',`<article class="card day-habits">${head('Твой ритм','Привычки на сегодня',btn('＋','newHabit','secondary'))}<div class="habit-progress"><b>${done} из ${habits.length}</b><span>${pct}%</span></div><div class="progress"><span style="width:${pct}%"></span></div><div class="list">${habits.slice(0,6).map(h=>`<label class="habit-row ${h.checks.includes(day)?'is-done':''}"><input type="checkbox" class="check" data-habit="${h.id}" ${h.checks.includes(day)?'checked':''}><span>${esc(h.name)}</span></label>`).join('')||empty('Добавь привычку и начни с малого.','✧')}</div>${habits.length>6?btn('Все привычки →','goHabits','ghost'):''}</article>`)}
  ${show('pomodoro',`<article class="focus-card"><div class="eyebrow">ВРЕМЯ ДЛЯ ГЛАВНОГО</div><h3>Одна задача.<br>Полное внимание.</h3><div class="focus-clock">${timer.running?`${String(Math.floor(timer.left/60)).padStart(2,'0')}:${String(timer.left%60).padStart(2,'0')}`:'25:00'}</div><p>Отложи отвлечения. Остальное подождёт.</p>${btn(timer.running?'Вернуться к таймеру →':'▶ Начать занятие','goPomodoro')}<span class="focus-star" aria-hidden="true">✦</span></article>`)}
  ${show('goals',`<article class="card day-goals">${head('К большему','Твои личные цели',btn('＋','newGoal','ghost'))}${goals.filter(g=>!g.done).slice(0,2).map(g=>`<div class="goal-mini"><div class="row between"><b>${esc(g.title)}</b><small>${Math.round(g.progress/g.target*100)}%</small></div><div class="progress"><span style="width:${Math.min(100,g.progress/g.target*100)}%"></span></div></div>`).join('')||empty('Чего хочется достичь?','◎')}</article>`)}
  </div></div><div class="day-footnote">✦ Ты двигаешься в своём темпе. Каждый шаг считается.</div>`;
}

function showHomePhotos(id){
  const task=cache.tasks?.find(t=>t.id===Number(id));
  if(!task)return;
  openModal(task.subject||'Фотографии задания',`<p class="muted">${esc(task.title)}</p><div class="task-photo-gallery">${(task.attachments||[]).map(a=>`<a href="/api/files/${encodeURIComponent(a.stored_name)}" target="_blank" rel="noopener"><img src="/api/files/${encodeURIComponent(a.stored_name)}" alt="${esc(a.filename||'Фото задания')}" loading="lazy"></a>`).join('')}</div>`);
}

function openModal(title,html){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#modal').classList.remove('hidden')}
function closeModal(){$('#modal').classList.add('hidden')};window.closeModal=closeModal;
function modalForm(fields,submit){openModal(fields.title,`<form id="dynamicForm">${fields.body}<div class="modal-actions"><button type="button" class="ghost" onclick="closeModal()">Отмена</button><button class="primary">Сохранить</button></div></form>`);$('#dynamicForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);try{await submit(f);closeModal();toast('Сохранено');renderPage()}catch(x){toast(x.message)}}}
function field(label,name,type='text',placeholder='',required=false){return `<label>${label}<input name="${name}" type="${type}" placeholder="${placeholder}" ${required?'required':''}></label>`}
function action(a){const actions={newTask,newHabit,newGoal,newLesson,newGrade,newEvent,newDeck,newCheat,goSchedule,goPomodoro,goTasks:()=>navigate('tasks'),goHabits:()=>navigate('habits'),prevMonth,nextMonth,saveWidgets,makeTelegramCode,saveNotif,newReminder,resetTimer,skipTimer,editProfile};(actions[a]||(()=>{}))()}
async function uploadTaskFiles(taskId, files){
  const images=Array.from(files||[]);
  if(!images.length)return {uploaded:0,failed:[]};
  const allowed=['image/jpeg','image/png','image/webp','image/gif'];
  const limit=8*1024*1024;
  for(const file of images){
    if(!allowed.includes(file.type))throw Error('Поддерживаются JPG, PNG, WEBP и GIF: '+file.name);
    if(file.size>limit)throw Error('Файл '+file.name+' больше 8 МБ');
  }
  const failed=[];let uploaded=0;
  for(const file of images){
    const data=new FormData();data.append('file',file,file.name);
    try{await api(`/tasks/${taskId}/attachments`,{method:'POST',body:data});uploaded++}
    catch(error){failed.push(`${file.name}: ${error.message}`)}
  }
  return {uploaded,failed};
}
function taskPhotoPicker(){return `<label>Фотографии задания (необязательно, можно несколько)<input id="taskPhotos" name="photos" type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple></label><div id="taskPhotoPreview" class="task-photo-preview"></div><p class="muted small">JPG, PNG, WEBP или GIF · до 8 МБ на фотографию</p>`}
function bindPhotoPreview(inputId='taskPhotos'){
  const input=document.getElementById(inputId),preview=document.getElementById('taskPhotoPreview');
  if(!input||!preview)return;
  input.addEventListener('change',()=>{
    preview.replaceChildren();
    Array.from(input.files||[]).forEach(file=>{
      const url=URL.createObjectURL(file),img=document.createElement('img');
      img.src=url;img.alt=file.name;img.title=file.name;
      img.onload=()=>URL.revokeObjectURL(url);
      preview.append(img);
    });
  });
}
async function newTask(){
  let subjects=[];
  try{const lessons=await api('/lessons');subjects=[...new Set(lessons.map(l=>l.subject?.trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ru'))}catch{}
  const subjectField=subjects.length?`<label>Предмет<select name="subject" required><option value="">Выбери предмет</option>${subjects.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('')}</select></label>`:field('Предмет','subject','text','Математика');
  openModal('Новое домашнее задание',`<form id="createTaskForm">${field('Название','title','text','Например, решить упражнения 1–5',true)}${subjectField}${field('Срок','due','date')}<label>Описание<textarea name="description"></textarea></label>${taskPhotoPicker()}<div class="modal-actions"><button type="button" class="ghost" onclick="closeModal()">Отмена</button><button type="submit" class="primary">Сохранить задание и фото</button></div></form>`);
  bindPhotoPreview();
  $('#createTaskForm').onsubmit=async e=>{
    e.preventDefault();const form=e.currentTarget,button=form.querySelector('[type="submit"]');
    const data=new FormData(form),photos=data.getAll('photos').filter(x=>x instanceof File&&x.size);
    data.delete('photos');
    button.disabled=true;button.textContent='Сохраняем…';
    try{
      const result=await api('/tasks',{method:'POST',body:JSON.stringify(Object.fromEntries(data))});
      const upload=await uploadTaskFiles(result.id,photos);
      closeModal();await renderPage();
      if(upload.failed.length){toast(`Задание сохранено, загружено фото: ${upload.uploaded}/${photos.length}`);alert('Не удалось загрузить некоторые фотографии. Задание сохранено, повтори загрузку кнопкой «＋ Фото».\n'+upload.failed.join('\n'))}
      else toast(photos.length?`Задание и ${upload.uploaded} фото сохранены`:'Домашнее задание сохранено');
    }catch(error){toast(error.message)}finally{button.disabled=false;button.textContent='Сохранить задание и фото'}
  };
}
