async function editLesson(id){
 const lessons=await api('/lessons');const l=lessons.find(x=>Number(x.id)===Number(id));
 if(!l){toast('Урок не найден');return}
 const days=['Понедельник','Вторник','Среда','Четверг','Пятница','Суббота','Воскресенье'];
 const safe=(v)=>esc(String(v??''));
 modalForm({title:'Изменить урок',body:`<label>Предмет<input name="subject" required maxlength="120" value="${safe(l.subject)}"></label><div class="form-grid"><label>День<select name="weekday">${days.map((d,i)=>`<option value="${i}" ${i===l.weekday?'selected':''}>${d}</option>`).join('')}</select></label><label>Номер урока<input name="period" type="number" min="1" max="20" required value="${l.period}"></label><label>Начало<input name="start" type="time" value="${safe(l.start)}"></label><label>Окончание<input name="finish" type="time" value="${safe(l.finish)}"></label><label>Кабинет<input name="room" maxlength="80" value="${safe(l.room)}"></label></div>`},async f=>api('/lessons/'+id,{method:'PUT',body:JSON.stringify(Object.fromEntries(f))}));
}
