async function editProfile(){await api('/profile',{method:'PUT',body:JSON.stringify({display_name:$('#displayName').value,timezone:$('#timezone').value})});me=await api('/me');showApp();toast('Профиль обновлён')}
function prevMonth(){calendarCursor.setMonth(calendarCursor.getMonth()-1);renderPage()}function nextMonth(){calendarCursor.setMonth(calendarCursor.getMonth()+1);renderPage()}function goSchedule(){navigate('schedule')}function goPomodoro(){navigate('pomodoro')}function resetTimer(){timerMode(timer.mode)}function skipTimer(){timerMode(timer.mode==='work'?'short':'work')}
$('#quickAdd').onclick=()=>{openModal('Быстрое добавление',`<div class="list">${[['Задание','newTask'],['Привычка','newHabit'],['Цель','newGoal'],['Событие','newEvent'],['Оценка','newGrade']].map(([n,a])=>`<button class="list-item quick-action" data-quick="${a}"><b>${n}</b><span class="muted">＋</span></button>`).join('')}</div>`);$$('[data-quick]').forEach(b=>b.onclick=()=>{closeModal();action(b.dataset.quick)})};
async function boot(){try{me=await api('/me');showApp()}catch(error){showAuth();if(error.message!=='Требуется вход'&&error.message!=='Сессия истекла'){console.error(error);$('#authError').textContent=error.message}}}

boot();

async function newReminder(existing=null){
 const r=existing||{title:'',kind:'schedule_tomorrow',send_time:'19:00',days:'0,1,2,3,4,5,6',enabled:true};
 const days=String(r.days).split(',');
 openModal(existing?'Изменить напоминание':'Новое напоминание',`<form id="reminderForm">
 <label>Тип<select name="kind" id="reminderKind">${[['schedule','📅 Расписание на сегодня'],['schedule_tomorrow','🌙 Расписание на завтра'],['habits','✅ Привычки'],['homework_eve','📚 Домашка на завтра'],['tasks','📝 Невыполненные задания'],['goals','🎯 Цели'],['evening_summary','🌙 Вечерняя сводка'],['general','🔔 Своё напоминание']].map(([v,t])=>`<option value="${v}" ${r.kind===v?'selected':''}>${t}</option>`).join('')}</select></label>
 <label>Название<input name="title" maxlength="120" required value="${esc(r.title)}" placeholder="Например, вечерние привычки"></label>
 <label>Время уведомления<input name="send_time" type="time" value="${esc(r.send_time)}" required></label>
 <div class="field"><label>Дни отправки</label><div class="week-days">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map((d,i)=>`<label><input type="checkbox" name="day" value="${i}" ${days.includes(String(i))?'checked':''}>${d}</label>`).join('')}</div></div>
 <label class="row"><input name="enabled" type="checkbox" ${r.enabled?'checked':''}> Включено</label>
 <div class="modal-actions"><button class="ghost" type="button" onclick="closeModal()">Отмена</button><button class="primary" type="submit">Сохранить напоминание</button></div></form>`);
 $('#reminderKind').onchange=e=>{let f=$('#reminderForm');let names={schedule:'Расписание на сегодня',schedule_tomorrow:'Расписание на завтра',habits:'Привычки',homework_eve:'Домашка на завтра',tasks:'Невыполненные задания',goals:'Цели',general:'Моё напоминание',evening_summary:'Вечерняя сводка'};f.elements.title.value=names[e.target.value];f.elements.send_time.value={schedule:'07:00',schedule_tomorrow:'19:00',habits:'09:00',homework_eve:'17:00',evening_summary:'20:00'}[e.target.value]||'19:00'};
 $('#reminderForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);let d={title:String(f.get('title')).trim(),kind:f.get('kind'),send_time:f.get('send_time'),days:f.getAll('day').map(Number),enabled:f.has('enabled'),mode:'fixed',event_source:'schedule',minutes_before:60};if(!d.days.length){toast('Выбери хотя бы один день');return}try{await api(existing?'/reminders/'+existing.id:'/reminders',{method:existing?'PUT':'POST',body:JSON.stringify(d)});closeModal();toast('Напоминание сохранено');renderPage()}catch(err){toast(err.message)}};
}
function bindReminderButtons(){
 $$('[data-reminderedit]').forEach(b=>b.onclick=async()=>{try{let items=await api('/reminders');let r=items.find(x=>x.id===Number(b.dataset.reminderedit));if(r)newReminder(r)}catch(e){toast(e.message)}});
 $$('[data-reminderdelete]').forEach(b=>b.onclick=async()=>{if(!confirm('Удалить напоминание?'))return;try{await api('/reminders/'+b.dataset.reminderdelete,{method:'DELETE'});renderPage()}catch(e){toast(e.message)}});
 $$('[data-remindertoggle]').forEach(b=>b.onchange=async()=>{try{await api('/reminders/'+b.dataset.remindertoggle,{method:'PUT',body:JSON.stringify({enabled:b.checked})});renderPage()}catch(e){toast(e.message)}});
 if($('#testReminder'))$('#testReminder').onclick=async()=>{try{await api('/reminders/test',{method:'POST',body:'{}'});toast('Проверь Telegram — тест отправлен')}catch(e){toast(e.message)}};
}

async function developerPage(){
 let profile={username:'saywest',telegram_id:'',avatar_url:''};
 try{profile=await api('/public/developer')}catch(e){}
 const username=String(profile.username||'saywest').replace(/[^a-zA-Z0-9_]/g,'');
 const id=String(profile.telegram_id||'').replace(/[^0-9]/g,'');
 const avatar=String(profile.avatar_url||'');
 const avatarSafe=/^https:\/\/[^\s"'<>]+$/i.test(avatar)?avatar:'';
 return `${head('Разработчик','Создатель и поддержка My-Study')}
 <div class="developer-glass"><div class="developer-glass-shine"></div>
 <div class="developer-profile"><div class="developer-avatar">${avatarSafe?`<img src="${esc(avatarSafe)}" alt="Аватар @${esc(username)}" onerror="this.style.display='none';this.nextElementSibling.style.display='grid'"><span style="display:none">✦</span>`:'<span>✦</span>'}</div>
 <div class="developer-details"><div class="developer-kicker">РАЗРАБОТЧИК MY-STUDY</div><h2>@${esc(username)}</h2><p>Telegram ID: <b>${id||'Не указан'}</b></p></div></div>
 <a class="developer-contact" href="https://t.me/${encodeURIComponent(username)}" target="_blank" rel="noopener noreferrer">✈ Написать</a></div>`;
}
async function subjectColorsPage(){let [lessons,notes]=await Promise.all([api('/lessons'),api('/lesson-notes')]);let subjects=[...new Set(lessons.map(x=>x.subject).filter(Boolean))].sort();window.subjectList=subjects;return `${head('Заметки к урокам','Личные заметки для каждого предмета')}<div class="card">${subjects.map((subject,i)=>`<div class="subject-config"><div class="grow"><b>${esc(subject)}</b><p class="muted small">${esc(notes[subject]||'Заметка пока не добавлена')}</p></div><button class="secondary" data-subjectnote="${i}">Изменить заметку</button></div>`).join('')||'<p class="muted">Добавь предметы в расписание, чтобы вести заметки.</p>'}</div>`}
const MY_THEMES=[['cosmos','Космос','#8b5cf6'],['emerald','Изумруд','#10b981'],['sapphire','Сапфир','#3b82f6'],['ruby','Рубин','#f43f5e'],['amethyst','Аметист','#a855f7'],['onyx','Оникс','#94a3b8']];
function applyTheme(name){if(!MY_THEMES.some(t=>t[0]===name))name='cosmos';document.documentElement.dataset.theme=name;localStorage.setItem('my-study-theme',name)}
applyTheme(localStorage.getItem('my-study-theme')||'cosmos');
async function appearancePage(){let [lessons,colors]=await Promise.all([api('/lessons'),api('/subject-colors')]);let subjects=[...new Set(lessons.map(x=>x.subject).filter(Boolean))].sort();window.subjectList=subjects;return `${head('Оформление','Тёмные темы и цвета предметов')}<div class="card"><h3>Тема сайта</h3><p class="muted small">Выбор сохраняется на этом устройстве.</p><div class="theme-grid">${MY_THEMES.map(([id,title,color])=>`<button class="theme-choice ${document.documentElement.dataset.theme===id?'selected':''}" data-theme-choice="${id}"><span class="theme-preview" style="--theme-swatch:${color}"></span><b>${title}</b></button>`).join('')}</div></div><div class="card"><h3>Цвета предметов</h3>${subjects.map((subject,i)=>`<div class="subject-config"><b>${esc(subject)}</b><input type="color" data-subjectcolor="${i}" value="${esc(colors[subject]||'#8b5cf6')}"></div>`).join('')||'<p class="muted">Сначала добавь уроки в расписание.</p>'}</div>`}

function habitStreak(checks){let dates=new Set(checks.map(String)),todayDate=new Date(),current=0,best=0,run=0;for(let i=365;i>=0;i--){let d=new Date(todayDate);d.setDate(d.getDate()-i);let key=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');if(dates.has(key)){run++;best=Math.max(best,run)}else run=0}for(let i=0;i<=365;i++){let d=new Date(todayDate);d.setDate(d.getDate()-i);let key=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');if(dates.has(key))current++;else if(i===0)continue;else break}return {current,best}}
async function searchPage(){return `${head('Поиск','Находи нужные записи в My-Study')}<div class="card search-panel"><label for="searchQuery">⌕ Поиск по твоим данным</label><input id="searchQuery" class="search-input" placeholder="Например: алгебра, контрольная, английский…" autocomplete="off"><div class="search-help"><b>Что можно найти?</b><p>📚 Домашние задания — по предмету и тексту</p><p>▦ Уроки — по названию предмета</p><p>📝 Заметки — по содержанию</p><p>🎯 Цели — по названию</p><p>▣ Карточки — по названию колоды</p><small>Введите минимум 2 символа. Нажмите на результат для перехода в раздел.</small></div><div id="searchResults" class="list" style="margin-top:14px"></div></div>`}
async function runSearch(query){let target=$('#searchResults');if(!target)return;let q=query.trim().toLocaleLowerCase('ru');if(q.length<2){target.innerHTML='<p class="muted">Введите минимум 2 символа.</p>';return}try{let [tasks,lessons,goals,decks,notes]=await Promise.all([api('/tasks'),api('/lessons'),api('/goals'),api('/decks'),api('/lesson-notes')]);let rows=[];for(let [label,items,pg,fn] of [['ДЗ',tasks,'tasks',x=>x.title+' '+x.subject+' '+x.description],['Урок',lessons,'schedule',x=>x.subject],['Цель',goals,'goals',x=>x.title+' '+x.description],['Карточки',decks,'cards',x=>x.title]])for(let item of items){let title=fn(item);if(title.toLocaleLowerCase('ru').includes(q))rows.push({label,title,pg})}for(let [subject,note] of Object.entries(notes))if((subject+' '+note).toLocaleLowerCase('ru').includes(q))rows.push({label:'Заметка',title:subject+': '+note,pg:'subjects'});target.innerHTML=rows.slice(0,40).map(x=>`<button class="list-item" data-goto="${x.pg}"><b>${esc(x.label)}</b><span>${esc(x.title.slice(0,130))}</span></button>`).join('')||'<p class="muted">Ничего не найдено</p>';$$('[data-goto]').forEach(x=>x.onclick=()=>navigate(x.dataset.goto))}catch(e){target.textContent=e.message}}

function setMobileMenu(open){document.body.classList.toggle('menu-open',open);$('#menuScrim')?.classList.toggle('hidden',!open);$('#mobileMenuToggle')?.setAttribute('aria-expanded',String(open));}
$$('[data-mobile-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.mobilePage));
$('#mobileMore').onclick=()=>setMobileMenu(!document.body.classList.contains('menu-open'));
$('#mobileMenuToggle').onclick=()=>setMobileMenu(!document.body.classList.contains('menu-open'));
$('#menuScrim').onclick=()=>setMobileMenu(false);
$('#themeHint').onclick=()=>navigate('appearance');
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();setMobileMenu(false)}});
